        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Add cream and cooked chicken.\n6. Simmer 10 minutes, serve with rice.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes", Steps = "1. Soak rice noodles in warm water 20 min.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: tamarind, fish sauce, sugar, chili.\n4. Stir-fry noodles with sauce.\n5. Add tofu and bean sprouts.\n6. Serve with peanuts, lime, green onions.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nNori\nCorn\nChashu pork", Steps = "1. Bring broth to a simmer.\n2. Whisk in miso paste and soy sauce.\n3. Cook ramen noodles separately.\n4. Prepare soft-boiled eggs (6.5 min).\n5. Assemble bowls: noodles, broth, toppings.\n6. Drizzle sesame oil and serve.", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes (center stays soft).\n7. Invert onto plates, serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Mix in diced onion, tomato, jalapeño.\n4. Add lime juice, cilantro, garlic, salt.\n5. Taste and adjust seasoning.\n6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 14 },
    };

    public static List<string> Categories =>
        Recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
}
"}

