@using RecipeCommunity.Models
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= DisplayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              aria-label="Rate @star stars">
            ★
        </span>
    }
    <span class="rating-info">
        @if (CurrentRating > 0)
        {
            <text>You rated: @CurrentRating/5</text>
        }
        else
        {
            <text>@AverageRating.ToString("F1") avg (@RatingCount ratings)</text>
        }
    </span>
</div>

<style>
    .star-rating {
        display: flex;
        align-items: center;
        gap: 2px;
    }
    .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star.filled {
        color: #f5a623;
    }
    .star:hover {
        color: #f5a623;
    }
    .rating-info {
        margin-left: 0.75rem;
        font-size: 0.9rem;
        color: #666;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int CurrentRating { get; set; }
    private int hoverRating;

    private int DisplayRating => hoverRating > 0 ? hoverRating : CurrentRating > 0 ? CurrentRating : (int)Math.Round(AverageRating);

    private void Rate(int stars)
    {
        CurrentRating = stars;
        // In a real app, persist rating to a database
        var recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == RecipeId);
        if (recipe != null)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

