    .ingredients, .steps { margin-top: 2rem; }
    .ingredients ul { list-style: disc; padding-left: 1.5rem; }
    .ingredients li { margin: 0.3rem 0; }
    .steps p { margin: 0.5rem 0; line-height: 1.6; }
</style>

@code {
    [Parameter] public int Id { get; set; }

