{"file_text": "@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@title</strong>" with the community.</p>
        <a href="/recipe/@newRecipeId">View your recipe →</a>
    </div>
}
else
{
    <form @onsubmit="HandleSubmit" class="recipe-form">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <input id="title" type="text" @bind="title" required placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <select id="category" @bind="category" required>
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeStore.Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </select>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <textarea id="ingredients" @bind="ingredients" rows="6" required
                      placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..."></textarea>
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <textarea id="steps" @bind="steps" rows="8" required
                      placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..."></textarea>
        </div>

        <button type="submit" class="submit-btn">Submit Recipe</button>
    </form>
}

<style>
    .recipe-form { max-width: 600px; margin-top: 1.5rem; }
    .form-group { margin-bottom: 1.25rem; }
    .form-group label { display: block; font-weight: 600; margin-bottom: 0.4rem; }
    .form-group input,
    .form-group select,
    .form-group textarea {
        width: 100%;
        padding: 0.6rem;
        border: 1px solid #ccc;
        border-radius: 6px;
        font-size: 1rem;
    }
    .form-group textarea { resize: vertical; }
    .submit-btn {
        background: #2e7d32;
        color: white;
        border: none;
        padding: 0.75rem 2rem;
        font-size: 1rem;
        border-radius: 6px;
        cursor: pointer;
        transition: background 0.2s;
    }
    .submit-btn:hover { background: #1b5e20; }
    .success-message {
        background: #e8f5e9;
        border: 1px solid #a5d6a7;
        border-radius: 8px;
        padding: 1.5rem;
        margin-top: 1rem;
    }
    .success-message a { color: #2e7d32; font-weight: 600; }
</style>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private int newRecipeId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
            return;

        newRecipeId = RecipeStore.Recipes.Max(r => r.Id) + 1;
        var recipe = new Recipe
        {
            Id = newRecipeId,
            Title = title,
            Category = string.IsNullOrWhiteSpace(category) ? "Other" : category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        };
        RecipeStore.Recipes.Add(recipe);
        submitted = true;
    }
}
", "path": "/tmp/sv-0666e301ff3241b6afa78ecedf2e8439/RecipeCommunity/Components/Pages/SubmitRecipe.razor"}

