+    <a href="/category/@recipe?.Category">@recipe?.Category</a> &rsaquo;
+    <span>@recipe?.Title</span>
+</nav>
+
+@if (recipe != null)
+{
+    <article class="recipe-detail">
+        <h1>@recipe.Title</h1>
+
+        <StarRating RecipeId="@recipe.Id"
+                    AverageRating="@recipe.AverageRating"
+                    RatingCount="@recipe.RatingCount" />
+
+        <section class="ingredients">
+            <h2>🧂 Ingredients</h2>
+            <ul>
+                @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
+                {
+                    <li>@ingredient</li>
+                }
+            </ul>
+        </section>
+
+        <section class="steps">
+            <h2>👨‍🍳 Instructions</h2>
+            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
+            {
+                <p>@step</p>
+            }
+        </section>
+    </article>
+}
+else
+{
+    <p>Recipe not found.</p>
+}
+
+<style>
+    nav { margin-bottom: 1.5rem; font-size: 0.9rem; }
+    nav a { text-decoration: none; color: #0066cc; }
+    .recipe-detail h1 { margin-bottom: 0.75rem; }
+    .ingredients, .steps { margin-top: 2rem; }
+    .ingredients ul { list-style: disc; padding-left: 1.5rem; }
+    .ingredients li { margin: 0.3rem 0; }
+    .steps p { margin: 0.5rem 0; line-height: 1.6; }
+</style>
+
+@code {
+    [Parameter] public int Id { get; set; }
+
+    private Recipe? recipe;
+
+    protected override void OnParametersSet()
+    {
+        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == Id);
+    }
+}
+

